<template>
  <div class="studio-page">
    <StudioTopbar v-model:search="search" :crumbs="selected ? ['Live Agents', selected.name] : ['Live Agents']" search-placeholder="Search running agents" @crumb="selected = null" />
    <div class="studio-content">
      <template v-if="selected">
        <button class="back" type="button" @click="selected = null">‹ Live Agents</button>
        <div class="card hero">
          <span class="fi purple big">◉</span><div><h1>{{ selected.name }}</h1><p>{{ selected.task }}</p>
            <div class="meta"><span class="st" :class="statusClass(selected.status)"><i />{{ statusLabel(selected) }} · {{ elapsed(selected.startedAt) }}</span><span>Tokens unavailable</span><span>{{ selected.model || 'Model unavailable' }}</span></div>
          </div><div class="acts"><button v-if="selected.canOpen" class="btn" type="button" @click="openLead(selected)">Open lead chat</button><button v-if="selected.canStop" class="btn danger" type="button" @click="stopTarget = selected">■ Stop</button></div>
        </div>
        <div class="dgrid">
          <div class="card box"><h2>Activity</h2>
            <div v-if="detailLoading" class="empty">Loading activity…</div>
            <div v-else-if="!detail?.entries.length" class="empty"><b>No recorded activity</b>This run has not written any conversation events yet.</div>
            <div v-else class="tl"><div v-for="(entry, index) in detail.entries" :key="index" class="ev" :class="{ tool: entry.kind === 'tool', you: entry.kind === 'user' }"><div class="who">{{ entryWho(entry) }} · {{ clock(entry.ts) }}</div><div class="msg">{{ entry.text }}</div></div></div>
            <form v-if="selected.canMessage" class="composer" @submit.prevent="sendMessage(selected)"><input v-model="message" placeholder="Message this agent…" aria-label="Message this agent"><button class="btn pri" type="submit" :disabled="busy || !message.trim()">{{ busy ? 'Sending…' : 'Send' }}</button></form><p v-if="actionError" class="error-text">{{ actionError }}</p>
          </div>
          <aside class="card side"><h3>Brief</h3><p class="brief">{{ selected.brief }}</p><h3>Run</h3><div class="kv"><span>Lead</span><b>{{ selected.lead }}</b></div><div class="kv"><span>Started</span><b>{{ when(selected.startedAt) }}</b></div><div class="kv"><span>Last check-in</span><b>{{ age(selected.lastActiveAt) }}</b></div><div class="kv"><span>Tokens</span><b>Unavailable</b></div></aside>
        </div>
      </template>
      <template v-else>
        <div class="tb"><h1>Live Agents</h1><span>Every agent running on this desktop right now, grouped by lead agent and chat.</span><div class="acts"><span class="st" :class="polling ? 'ok' : 'bad'"><i />{{ polling ? `streaming · updated ${age(data.updatedAt)}` : 'updates paused' }}</span></div></div>
        <div class="stats">
          <div class="card stat"><div class="lbl"><span class="dot success" />Agents running</div><b>{{ runningCount }}</b><small>across {{ chatCount }} lead {{ chatCount === 1 ? 'agent' : 'agents' }}</small></div>
          <div class="card stat"><div class="lbl"><span class="dot accent" />Chats</div><b>{{ chatCount }}</b><small>{{ chatNames || 'No active chats' }}</small></div>
          <div class="card stat"><div class="lbl"><span class="dot workflow" />Workflow runs</div><b>{{ workflowCount }}</b><small>{{ workflowNames || 'No active workflows' }}</small></div>
          <div class="card stat"><div class="lbl"><span class="dot warning" />Needs attention</div><b>{{ attentionCount }}</b><small>{{ attentionCount ? 'stalled, quiet, or blocked' : 'Nothing needs attention' }}</small></div>
        </div>
        <div v-if="loading" class="card empty">Loading live agents…</div>
        <div v-else-if="!filteredGroups.length" class="card empty"><b>{{ search ? 'No matching agents' : 'Nothing is running right now' }}</b>{{ search ? 'Try another search.' : 'Active chats and runs will appear here.' }}</div>
        <div v-for="group in filteredGroups" :key="group.id" class="card group">
          <div class="group-head"><span class="fi blue">◉</span><div><b>{{ group.name }}</b><small> · {{ group.meta }} · {{ elapsed(group.startedAt) }}</small></div><div class="acts"><button v-if="group.agent" class="btn sm" type="button" @click="openAgentChat(group.agent)">Open chat</button></div></div>
          <div v-for="row in group.rows" :key="row.id" class="agent-row" :class="{ click: row.kind === 'task' }" @click="row.kind === 'task' && selectRow(row)"><span class="tree">└</span><div><b>{{ row.name }}</b><small>{{ row.task }}</small></div><span class="st" :class="statusClass(row.status)"><i />{{ statusLabel(row) }} · {{ elapsed(row.startedAt) }}</span><span class="mono muted">—</span><div class="row-actions"><button v-if="row.canMessage" class="btn sm" type="button" @click.stop="messageTarget = row">Message</button><button v-if="row.canStop" class="btn sm danger" type="button" @click.stop="stopTarget = row">Stop</button></div></div>
        </div>
      </template>
    </div>
    <div v-if="messageTarget" class="overlay" @click.self="messageTarget = null"><form class="card modal" @submit.prevent="sendMessage(messageTarget)"><h2>Message {{ messageTarget.name }}</h2><textarea v-model="message" rows="4" placeholder="What should this agent know?" /><p v-if="actionError" class="error-text">{{ actionError }}</p><div class="modal-actions"><button class="btn" type="button" @click="messageTarget = null">Cancel</button><button class="btn pri" type="submit" :disabled="busy || !message.trim()">{{ busy ? 'Sending…' : 'Send message' }}</button></div></form></div>
    <div v-if="stopTarget" class="overlay" @click.self="stopTarget = null"><div class="card modal"><h2>Stop {{ stopTarget.name }}?</h2><p>The current tool call may finish before the run stops.</p><p v-if="actionError" class="error-text">{{ actionError }}</p><div class="modal-actions"><button class="btn" type="button" @click="stopTarget = null">Cancel</button><button class="btn danger" type="button" :disabled="busy" @click="stopRun">{{ busy ? 'Stopping…' : 'Stop run' }}</button></div></div></div>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import type { AgentConversationDetail, AgentsListResponse } from '@pkg/main/agentsIpc';
import { ipcRenderer } from '@pkg/utils/ipcRenderer';
import StudioTopbar from './StudioTopbar.vue';

type Agent = AgentsListResponse['agents'][number]; type Job = AgentsListResponse['jobs'][number]; type Task = Job['tasks'][number]; type RowStatus = 'running' | 'quiet' | 'blocked' | 'failed' | 'workflow';
interface LiveRow { id:string; kind:'task'|'workflow'; name:string; task:string; brief:string; lead:string; status:RowStatus; startedAt:number; lastActiveAt:number; model?:string; jobId?:string; taskIndex?:number; threadId?:string; parentThreadId?:string; canMessage:boolean; canStop:boolean; canOpen:boolean }
interface LiveGroup { id:string; name:string; meta:string; startedAt:number; agent?:Agent; rows:LiveRow[] }
const QUIET_MS=8*60_000; const data=ref<AgentsListResponse>({agents:[],heartbeat:null,jobs:[],workflowRuns:[],updatedAt:0}); const now=ref(Date.now()); const loading=ref(true); const polling=ref(true); const search=ref(''); const selected=ref<LiveRow|null>(null); const detail=ref<AgentConversationDetail|null>(null); const detailLoading=ref(false); const messageTarget=ref<LiveRow|null>(null); const stopTarget=ref<LiveRow|null>(null); const message=ref(''); const busy=ref(false); const actionError=ref(''); let pollTimer:ReturnType<typeof setInterval>|undefined; let clockTimer:ReturnType<typeof setInterval>|undefined;
function rowStatus(job:Job,task:Task):RowStatus { if(task.status==='blocked')return'blocked'; if(job.status==='failed'||task.status==='error')return'failed'; if(task.waitingForHuman||now.value-(task.latestCheckin?.createdAt??task.lastActivityAt??task.startedAt)>=QUIET_MS)return'quiet'; return'running' }
function taskRow(job:Job,task:Task,lead:string):LiveRow{return{id:`${job.jobId}:${task.taskIndex}`,kind:'task',name:task.label||task.agentId,task:task.latestCheckin?.summary||task.lastActivity||task.taskId||'Working',brief:job.parentTitle||task.taskId||'No brief recorded.',lead,status:rowStatus(job,task),startedAt:task.startedAt,lastActiveAt:task.latestCheckin?.createdAt??task.lastActivityAt??task.startedAt,model:task.model,jobId:job.jobId,taskIndex:task.taskIndex,threadId:task.threadId,parentThreadId:job.parentThreadId,canMessage:job.status==='running'&&['queued','running'].includes(task.status),canStop:job.status==='running'&&['queued','running'].includes(task.status),canOpen:!!(job.parentThreadId&&task.threadId)}}
const groups=computed<LiveGroup[]>(()=>{const result:LiveGroup[]=[];const grouped=new Map<string,Job[]>();for(const job of data.value.jobs.filter(j=>!['completed','stopped'].includes(j.status))){const key=job.parentThreadId||job.parentChannel||job.jobId;grouped.set(key,[...(grouped.get(key)||[]),job])}for(const[key,jobs]of grouped){const first=jobs[0];const agent=data.value.agents.find(a=>a.channel===first.parentChannel||a.agentId===first.parentAgentId);const name=agent?.name||first.parentAgentId||first.parentChannel||'Agent run';const rows=jobs.flatMap(j=>j.tasks.filter(t=>!['completed','stopped'].includes(t.status)).map(t=>taskRow(j,t,name)));if(rows.length)result.push({id:key,name,meta:first.parentChannel||'agent chat',startedAt:Math.min(...rows.map(r=>r.startedAt)),agent,rows})}if(data.value.workflowRuns.length)result.push({id:'workflows',name:'Workflow runs',meta:'automated work',startedAt:Math.min(...data.value.workflowRuns.map(r=>r.startedAt)),rows:data.value.workflowRuns.map(run=>({id:run.executionId,kind:'workflow',name:run.name,task:run.error||run.activity,brief:run.slug,lead:'Workflow manager',status:run.status==='failed'?'failed':run.status==='suspended'?'quiet':'workflow',startedAt:run.startedAt,lastActiveAt:run.updatedAt,canMessage:false,canStop:false,canOpen:false}))});return result});
const filteredGroups=computed(()=>{const q=search.value.trim().toLowerCase();if(!q)return groups.value;return groups.value.flatMap(g=>{const rows=g.rows.filter(r=>[r.name,r.task,r.model].some(v=>v?.toLowerCase().includes(q)));return g.name.toLowerCase().includes(q)?[g]:rows.length?[{...g,rows}]:[]})}); const allRows=computed(()=>groups.value.flatMap(g=>g.rows)); const runningCount=computed(()=>allRows.value.filter(r=>r.status==='running'||r.status==='workflow').length); const chatCount=computed(()=>groups.value.filter(g=>g.id!=='workflows').length); const chatNames=computed(()=>groups.value.filter(g=>g.id!=='workflows').map(g=>g.name).join(' · ')); const workflowCount=computed(()=>data.value.workflowRuns.length); const workflowNames=computed(()=>data.value.workflowRuns.map(r=>r.name).slice(0,2).join(' · ')); const attentionCount=computed(()=>allRows.value.filter(r=>['quiet','blocked','failed'].includes(r.status)).length);
async function load(){try{data.value=await ipcRenderer.invoke('agents:list');polling.value=true;if(selected.value){const fresh=allRows.value.find(r=>r.id===selected.value?.id);if(fresh)selected.value=fresh}}catch{polling.value=false}finally{loading.value=false}}
async function loadDetail(){if(!selected.value?.threadId){detail.value=null;return}detailLoading.value=true;try{detail.value=await ipcRenderer.invoke('agents:conversation',selected.value.threadId)}catch{detail.value=null}finally{detailLoading.value=false}}
function selectRow(row:LiveRow){selected.value=row;actionError.value='';loadDetail()} async function sendMessage(row:LiveRow){if(!row.jobId||row.taskIndex===undefined||!message.value.trim())return;busy.value=true;actionError.value='';const result=await ipcRenderer.invoke('agents:message-job',row.jobId,row.taskIndex,message.value.trim());busy.value=false;if(!result.ok){actionError.value=result.error||'The message could not be delivered.';return}message.value='';messageTarget.value=null;await load()} async function stopRun(){const row=stopTarget.value;if(!row?.jobId)return;busy.value=true;actionError.value='';const result=await ipcRenderer.invoke('agents:stop-job',row.jobId);busy.value=false;if(!result.ok){actionError.value=result.error||'The run could not be stopped.';return}stopTarget.value=null;selected.value=null;await load()} async function openLead(row:LiveRow){if(row.jobId&&row.parentThreadId&&row.taskIndex!==undefined)await ipcRenderer.invoke('agents:open-job-in-tab',row.jobId,row.parentThreadId,row.taskIndex)}
function openAgentChat(agent:Agent){selected.value={id:`agent:${agent.channel}`,kind:'task',name:agent.name,task:agent.statusNote||'Active chat',brief:agent.statusNote||'No brief recorded.',lead:agent.name,status:agent.status==='running'?'running':'quiet',startedAt:agent.startedAt,lastActiveAt:agent.lastActiveAt,canMessage:false,canStop:false,canOpen:false}}
function statusClass(status:RowStatus){return status==='running'||status==='workflow'?'run':status==='failed'||status==='blocked'?'bad':'warn'} function statusLabel(row:Pick<LiveRow,'status'>){return({running:'Working',workflow:'Running',quiet:'Quiet',blocked:'Blocked',failed:'Failed'}as const)[row.status]} function elapsed(ts:number){const s=Math.max(0,Math.floor((now.value-ts)/1000));if(s<60)return`${s}s`;if(s<3600)return`${Math.floor(s/60)} min`;return`${Math.floor(s/3600)}h ${Math.floor(s%3600/60)}m`} function age(ts:number){return ts?`${elapsed(ts)} ago`:'not recorded'} function when(ts:number){return new Date(ts).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})} function clock(ts:string){const date=new Date(ts);return Number.isNaN(date.getTime())?'':date.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})} function entryWho(entry:AgentConversationDetail['entries'][number]){if(entry.kind==='user')return'You';if(entry.kind==='tool')return entry.toolName||'Tool';if(entry.kind==='event')return'Run';return selected.value?.name||'Agent'}
watch(()=>selected.value?.threadId,loadDetail);onMounted(()=>{load();pollTimer=setInterval(()=>{load();if(selected.value)loadDetail()},3_000);clockTimer=setInterval(()=>{now.value=Date.now()},1_000)});onUnmounted(()=>{if(pollTimer)clearInterval(pollTimer);if(clockTimer)clearInterval(clockTimer)});
</script>

<style scoped lang="scss">
@import '@pkg/assets/styles/studio-ui.scss';
.group{margin-bottom:12px}.group-head{display:flex;align-items:center;gap:10px;padding:12px 14px;border-bottom:1px solid var(--uc-line)}.group-head small,.muted{color:var(--uc-dim)}.group-head .acts{margin-left:auto}.agent-row{display:grid;grid-template-columns:22px minmax(220px,1fr) 160px 90px auto;align-items:center;gap:10px;padding:11px 14px;border-bottom:1px solid var(--uc-line)}.agent-row:last-child{border-bottom:0}.agent-row.click{cursor:pointer}.agent-row.click:hover{background:var(--uc-paper)}.agent-row b,.agent-row small{display:block}.agent-row small{margin-top:2px;color:var(--uc-dim)}.tree{color:var(--uc-dim)}.row-actions{display:flex;justify-content:flex-end;gap:6px}.dot.success{background:var(--uc-success)}.dot.accent{background:var(--uc-accent)}.dot.workflow{background:#7656d8}.dot.warning{background:#c47a00}.tl{margin:14px 0}.ev{padding:12px 0 12px 18px;border-left:2px solid var(--uc-accent-line)}.ev.tool{border-color:var(--uc-line-strong)}.ev.you{border-color:#7656d8}.who{margin-bottom:4px;color:var(--uc-dim);font-size:11px}.msg{color:var(--uc-muted);line-height:1.5;white-space:pre-wrap}.composer{display:flex;gap:8px;margin-top:18px}.composer input,.modal textarea{flex:1;padding:9px 11px;border:1px solid var(--uc-line-strong);border-radius:8px;background:var(--uc-card);color:var(--uc-text);font:inherit}.brief{padding:12px 16px!important}.overlay{position:absolute;inset:0;z-index:20;display:grid;place-items:center;padding:24px;background:color-mix(in srgb,#000 45%,transparent)}.modal{width:min(480px,100%);padding:20px}.modal h2{margin:0 0 8px}.modal textarea{width:100%;margin:12px 0;resize:vertical}.modal-actions{display:flex;justify-content:flex-end;gap:8px}.error-text{color:var(--uc-danger)!important}.hero>div:nth-child(2){min-width:0;flex:1}@media(max-width:900px){.agent-row{grid-template-columns:20px 1fr}.agent-row>.st,.agent-row>.mono,.row-actions{grid-column:2}.hero{flex-wrap:wrap}.hero .acts{width:100%;margin-left:82px}}
</style>
